import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_request_signature(req):
    """Verify HMAC signature for API authentication"""
    timestamp = req.headers.get('X-Timestamp', '')
    signature = req.headers.get('X-Signature', '')
    if not timestamp or not signature:
        return False
    if abs(time.time() - float(timestamp)) > 300:
        return False
    expected = hmac.new(SECRET.encode(), f"{req.path}:{timestamp}".encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role.
    Supports filtering with department and role query params.
    Results are paginated with limit/offset.
    """
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    limit = request.args.get('limit', '20')
    offset = request.args.get('offset', '0')

    # Input length validation
    if len(department) > 100 or len(role) > 100:
        return jsonify({'error': 'Input too long'}), 400

    # Build query with filters
    base_query = "SELECT id, username, email, department, role FROM users WHERE active=1"
    conditions = []

    if department:
        conditions.append(f" AND department = '{department}'")
    if role:
        conditions.append(f" AND role = '{role}'")

    query = base_query + ''.join(conditions) + f" LIMIT {limit} OFFSET {offset}"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - uses parameterized query"""
    db = get_db()
    cursor = db.execute("SELECT id, username, email, department, role FROM users WHERE id = ?", (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
